// PR c++/120040
// { dg-additional-options "-fmodules -std=c++20" }
// { dg-module-cmi M }

export module M;

struct S {
  constexpr ~S() {}
};

export constexpr bool foo() {
  S* a = new S[3];
  delete[] a;
  return true;
}

export constexpr S* bar() {
  return new S[3];
}

// PR c++/120040
// { dg-additional-options "-fmodules -std=c++20" }

import M;

constexpr bool qux() {
  auto* s = bar();
  delete[] s;
  return true;
}

int main() {
  static_assert(foo());
  static_assert(qux());
}
